{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_text",
        "subtitle_text",
        "email_card"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Project X Deadline Reminder",
        "variant": "h1"
      },
      "children": []
    },
    "subtitle_text": {
      "type": "Text",
      "props": {
        "text": "Draft Email for Team",
        "variant": "h2"
      },
      "children": []
    },
    "email_card": {
      "type": "Card",
      "props": {},
      "children": [
        "email_header_stack",
        "email_body_stack",
        "email_signature_stack"
      ]
    },
    "email_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "to_line_stack",
        "subject_line_stack",
        "header_divider"
      ]
    },
    "to_line_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "to_label",
        "to_value"
      ]
    },
    "to_label": {
      "type": "Text",
      "props": {
        "text": "To:",
        "variant": "label"
      },
      "children": []
    },
    "to_value": {
      "type": "Text",
      "props": {
        "text": "team@example.com"
      },
      "children": []
    },
    "subject_line_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "subject_label",
        "subject_value"
      ]
    },
    "subject_label": {
      "type": "Text",
      "props": {
        "text": "Subject:",
        "variant": "label"
      },
      "children": []
    },
    "subject_value": {
      "type": "Text",
      "props": {
        "text": "Reminder: Project X Deadline Approaching"
      },
      "children": []
    },
    "header_divider": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "email_body_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "body_p1",
        "body_p2",
        "body_p3",
        "body_p4",
        "body_p5"
      ]
    },
    "body_p1": {
      "type": "Text",
      "props": {
        "text": "Hi Team,"
      },
      "children": []
    },
    "body_p2": {
      "type": "Text",
      "props": {
        "text": "This is a friendly reminder that the deadline for Project X is fast approaching."
      },
      "children": []
    },
    "body_p3": {
      "type": "Text",
      "props": {
        "text": "Please ensure all final submissions are completed by Tuesday, June 25, 2024, at 5:00 PM GMT. Your timely contributions are crucial for the successful completion of this project."
      },
      "children": []
    },
    "body_p4": {
      "type": "Text",
      "props": {
        "text": "If you have any last-minute questions or require assistance, please reach out to the project lead as soon as possible."
      },
      "children": []
    },
    "body_p5": {
      "type": "Text",
      "props": {
        "text": "Thank you for your hard work!"
      },
      "children": []
    },
    "email_signature_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "signature_line1",
        "signature_line2"
      ]
    },
    "signature_line1": {
      "type": "Text",
      "props": {
        "text": "Best regards,"
      },
      "children": []
    },
    "signature_line2": {
      "type": "Text",
      "props": {
        "text": "[Your Name/Project Management]"
      },
      "children": []
    }
  }
}
